class Solution:
    def findRotateSteps(self, ring: str, key: str) -> int:
        lookup = collections.defaultdict(list)
        for i in range(len(ring)):
            lookup[ring[i]].append(i)

        dp = [[0] * len(ring) for _ in range(2)]
        prev = [0]
        for i in range(1, len(key)+1):
            dp[i%2] = [float("inf")] * len(ring)
            for j in lookup[key[i-1]]:
                for k in prev:
                    dp[i%2][j] = min(dp[i%2][j],
                                     min((k+len(ring)-j) % len(ring), \
                                         (j+len(ring)-k) % len(ring)) + \
                                     dp[(i-1) % 2][k])
            prev = lookup[key[i-1]]
        return min(dp[len(key)%2]) + len(key)

class Solution:
    def longestPalindromeSubseq(self, s: str) -> int:
        dp = [[0 for _ in range(len(s))] for _ in range(len(s))]
        for k in range(1, len(s) + 1):
            for i in range(len(s) - k + 1):
                j = k + i - 1
                if i == j:
                    dp[i][j] = 1
                elif i + 1 == j and s[i] == s[j]:
                    dp[i][j] = 2
                elif s[i] == s[j]:
                    dp[i][j] = dp[i+1][j-1] + 2
                else:
                    dp[i][j] = max(dp[i+1][j], dp[i][j-1])
        return dp[0][-1]

class Solution:
    def longestPalindromeSubseq(self, s: str) -> int:
        if s == s[::-1]:  # optional, to optimize special case
            return len(s)

        dp = [[1] * len(s) for _ in range(2)]
        for i in reversed(range(len(s))):
            for j in range(i+1, len(s)):
                if s[i] == s[j]:
                    dp[i%2][j] = 2 + dp[(i+1)%2][j-1] if i+1 <= j-1 else 2
                else:
                    dp[i%2][j] = max(dp[(i+1)%2][j], dp[i%2][j-1])
        return dp[0][-1]

class Solution:
    def detectCapitalUse(self, word: str) -> bool:
        l=len(word)
        if l==1:
            return True
        if word[0]==word[0].lower() and word[1]==word[1].upper():
            return False

        u=False
        if word[0]==word[0].upper():
            if word[1]==word[1].upper():
                u=True

        for i in word[2:]:
            if i==i.upper() and u==False:
                return False
            elif i==i.lower() and u==True:
                return False
        return True

